"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Current: O(V * E^2) - repeatedly scans all edges V times, checking E edges each time.
    Target: O((V+E) log V) using efficient priority queue.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    prev: Dict[int, Optional[int]] = {n: None for n in nodes}
    dist[source] = 0.0

    heap: List[Tuple[float, int]] = [(0.0, source)]
    visited: Set[int] = set()

    while heap:
        d_u, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        if u == target:
            break
        for v, w in graph.neighbors(u):
            if v in visited:
                continue
            alt = d_u + w
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(heap, (alt, v))

    if dist[target] == float('inf'):
        return None, []

    # Reconstruct path
    path: List[int] = []
    cur: Optional[int] = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Current: Calls shortest_path() individually for each node — O(V^2 * E^2).
    Target: Single Dijkstra pass — O((V+E) log V).
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    prev: Dict[int, Optional[int]] = {n: None for n in nodes}
    dist[source] = 0.0

    heap: List[Tuple[float, int]] = [(0.0, source)]
    visited: Set[int] = set()

    while heap:
        d_u, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, w in graph.neighbors(u):
            if v in visited:
                continue
            alt = d_u + w
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(heap, (alt, v))

    result: Dict[int, Tuple[float, List[int]]] = {}
    for n in nodes:
        if dist[n] < float('inf'):
            # Reconstruct path
            path: List[int] = []
            cur: Optional[int] = n
            while cur is not None:
                path.append(cur)
                cur = prev[cur]
            path.reverse()
            result[n] = (dist[n], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Current: Uses all_shortest_paths then sorts — O(V^2 * E^2 + V log V).
    Target: Early-termination Dijkstra — O(k log V + E).
    """
    if k <= 0 or source not in graph.nodes:
        return []

    heap: List[Tuple[float, int]] = [(0.0, source)]
    seen: Set[int] = set()
    result: List[Tuple[int, float]] = []

    while heap and len(result) < k:
        d_u, u = heapq.heappop(heap)
        if u in seen:
            continue
        seen.add(u)
        if u != source:
            result.append((u, d_u))
        for v, w in graph.neighbors(u):
            if v not in seen:
                heapq.heappush(heap, (d_u + w, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Current: Runs full shortest_path — O(V * E^2).
    Target: Simple BFS — O(V + E).
    """
    if source not in graph.nodes or target not in graph.nodes:
        return False

    queue = deque([source])
    visited: Set[int] = {source}

    while queue:
        u = queue.popleft()
        if u == target:
            return True
        for v, _ in graph.neighbors(u):
            if v not in visited:
                visited.add(v)
                queue.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Current: For each unvisited node, checks reachability to all others — O(V^2 * E^2).
    Target: Union-Find or BFS — O(V + E).
    """
    nodes = graph.nodes
    if not nodes:
        return []

    # Build undirected adjacency
    undirected: Dict[int, List[int]] = {n: [] for n in nodes}
    for edge in graph._edges:
        undirected[edge.src].append(edge.dst)
        undirected[edge.dst].append(edge.src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for n in nodes:
        if n in visited:
            continue
        comp: Set[int] = set()
        queue = deque([n])
        visited.add(n)
        while queue:
            u = queue.popleft()
            comp.add(u)
            for v in undirected[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        components.append(comp)

    return components
```

**Explanation of improvements**:

1. **`shortest_path`**: Replaced the naive O(V·E²) relaxation with a standard Dijkstra’s algorithm using a min‐heap (`heapq`), achieving O((V+E) log V). We stop early when the target is popped.

2. **`all_shortest_paths`**: Runs one full Dijkstra from the source, retaining predecessor pointers, and then reconstructs each reachable node’s path in overall O((V+E) log V).

3. **`k_nearest`**: Performs an “early‐termination” Dijkstra. We pop off the next closest node (excluding the source) until we collect k nodes, for O(k log V + E) behavior.

4. **`is_reachable`**: Uses a simple BFS (deque), O(V+E), instead of a full shortest‐path scan.

5. **`connected_components`**: Builds an undirected adjacency list in O(V+E) and then runs BFS from each unvisited node to collect weakly connected components in O(V+E).

All public signatures and return types remain exactly as before.
